message.content:
{
  "title": "The Rescue at Hollowcrown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A rescue party gathers at the edge of the ruined city.",
      "visual_description": "Four travelers crouch on a windswept hill at dawn, looking down at a crumbling royal city wreathed in mist, broken spires piercing the clouds.",
      "characters": ["Captain Aren", "Mira the Mapwright", "Brindle the Scout", "Sable the Spellbinder"]
    },
    {
      "scene_number": 2,
      "caption": "Mira unrolls a map of the lost royal city.",
      "visual_description": "Close-up of a weathered parchment held down by stones, ink lines tracing castle gates, towers, and a single red circle around a dungeon keep.",
      "characters": ["Mira the Mapwright", "Captain Aren"]
    },
    {
      "scene_number": 3,
      "caption": "They slip past the cracked castle gates.",
      "visual_description": "Massive iron gates hang twisted from their hinges; the party tiptoes through long shadows cast by toppled statues of forgotten kings.",
      "characters": ["Captain Aren", "Brindle the Scout", "Sable the Spellbinder", "Mira the Mapwright"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower looms, whispering temptations.",
      "visual_description": "A leaning black tower with violet runes glowing along its stones; spectral hands reach from the windows toward the travelers below.",
      "characters": ["Sable the Spellbinder", "Captain Aren"]
    },
    {
      "scene_number": 5,
      "caption": "Brindle resists the lure of dragon-hoard rumors.",
      "visual_description": "A peasant in tattered cloak gestures wildly toward a smoking pit, gold coins scattered at the edge; Brindle shakes his head and pulls the party onward.",
      "characters": ["Brindle the Scout", "Old Hask the Beggar", "Captain Aren"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townspeople huddle in a market ruin.",
      "visual_description": "A collapsed bazaar with overturned stalls; women and children clutch each other beneath a torn awning as the party approaches with raised hands.",
      "characters": ["Captain Aren", "Mira the Mapwright", "Goodwife Ellin", "Tomkin the Orphan"]
    },
    {
      "scene_number": 7,
      "caption": "Tomkin reveals where the captive is held.",
      "visual_description": "A small boy traces a path in the ash on the cobblestones, pointing toward a distant keep crowned by a black banner.",
      "characters": ["Tomkin the Orphan", "Mira the Mapwright", "Captain Aren"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol marches through the square.",
      "visual_description": "Six soldiers in blackened plate stomp past a fountain, halberds gleaming; the party presses flat against a broken wall in deep shadow.",
      "characters": ["Captain Aren", "Brindle the Scout", "Sable the Spellbinder", "Mira the Mapwright"]
    },
    {
      "scene_number": 9,
      "caption": "Sable lulls a drowsy gate official to deeper sleep.",
      "visual_description": "A round, snoring clerk slumps over a podium of keys; Sable trails silver smoke from her fingertips over his head while Brindle lifts a ring of keys.",
      "characters": ["Sable the Spellbinder", "Brindle the Scout", "Warden Pomly"]
    },
    {
      "scene_number": 10,
      "caption": "They confront a sealed magic door.",
      "visual_description": "An obsidian door inlaid with shifting silver glyphs blocks a corridor; the glyphs rearrange whenever the party blinks.",
      "characters": ["Sable the Spellbinder", "Captain Aren", "Mira the Mapwright"]
    },
    {
      "scene_number": 11,
      "caption": "Mira solves the door's shifting riddle.",
      "visual_description": "Mira sketches glyphs into a notebook, comparing them to her map; the silver patterns lock into a single open archway of pale light.",
      "characters": ["Mira the Mapwright", "Sable the Spellbinder"]
    },
    {
      "scene_number": 12,
      "caption": "They descend into the banner-draped throne hall.",
      "visual_description": "Tattered royal banners in crimson and gold hang from a vaulted ceiling above a cracked throne; dust motes drift in shafts of broken stained-glass light.",
      "characters": ["Captain Aren", "Brindle the Scout", "Sable the Spellbinder", "Mira the Mapwright"]
    },
    {
      "scene_number": 13,
      "caption": "The captive princess is found chained in the vault.",
      "visual_description": "A young woman in a torn green gown sits straight-backed against a stone pillar, iron cuffs around her wrists, eyes fierce and unbroken.",
      "characters": ["Princess Liora", "Captain Aren", "Brindle the Scout"]
    },
    {
      "scene_number": 14,
      "caption": "Brindle picks the locks while alarms begin to ring.",
      "visual_description": "Close-up of nimble fingers working a curved pick in an iron cuff; in the background, a brass bell shudders in a high arched window.",
      "characters": ["Brindle the Scout", "Princess Liora", "Captain Aren"]
    },
    {
      "scene_number": 15,
      "caption": "The patrol returns and the chase begins.",
      "visual_description": "Black-armored soldiers pour through an archway with torches and crossbows; the party sprints down a corridor lined with shattered mirrors.",
      "characters": ["Captain Aren", "Princess Liora", "Brindle the Scout", "Sable the Spellbinder", "Mira the Mapwright"]
    },
    {
      "scene_number": 16,
      "caption": "Sable conjures a wall of mist to slow pursuit.",
      "visual_description": "Thick silver fog billows up from Sable's outstretched palms, swallowing the corridor behind them; shadowy figures grope helplessly inside.",
      "characters": ["Sable the Spellbinder", "Captain Aren", "Princess Liora"]
    },
    {
      "scene_number": 17,
      "caption": "They race onto the last bridge above a foaming gorge.",
      "visual_description": "A narrow stone bridge arcs over a deep river chasm; the party runs across as ropes snap and stones crumble behind their heels.",
      "characters": ["Captain Aren", "Princess Liora", "Brindle the Scout", "Sable the Spellbinder", "Mira the Mapwright"]
    },
    {
      "scene_number": 18,
      "caption": "On the far side, they look back at the ruined city.",
      "visual_description": "The rescuers stand on a forested ridge at sunset, the broken city behind them shrouded in violet smoke; Princess Liora pulls a hood up, eyes set on the road ahead.",
      "characters": ["Princess Liora", "Captain Aren", "Mira the Mapwright", "Brindle the Scout", "Sable the Spellbinder"]
    }
  ]
}

